/**
 * Versioned contract for the recipe GENERATED by the model (issue #43).
 *
 * Distinct from the storage recipe contract (src/recipes/contract.ts in the
 * app): this one validates what a model emits, in Chrome and in Node, with a
 * strict parse and a strict schema:
 *
 *   - the raw output must be pure JSON — no Markdown, no fenced block, no
 *     trailing prose (strict parse, then validation);
 *   - title non-empty, servings a positive integer, ingredients non-empty
 *     with strictly positive quantities and units from a controlled list,
 *     steps ordered non-empty strings;
 *   - optional durations (prep/cook minutes) are indicative and must never be
 *     presented as verified;
 *   - additional fields are explicitly forbidden (fixed allowlist), and any
 *     product identifier inside an ingredient (id, product_id, ean, ref…) is
 *     rejected: the model may never link an ingredient to a catalogue entry.
 *
 * On invalidity the consumer performs AT MOST ONE guided repair round
 * (see buildRepairPrompt), then surfaces an explicit error without any
 * cart mutation. No partial recipe is ever accepted.
 */

export const GENERATED_RECIPE_SCHEMA_VERSION = 1 as const;

/** Controlled units the model may use for ingredient quantities. */
export const GENERATED_RECIPE_UNITS = [
  "g",
  "kg",
  "ml",
  "cl",
  "l",
  "pièce",
  "tranche",
  "sachet",
  "boîte",
  "gousse",
  "pincée",
  "botte",
  "pot",
  "cuillère à soupe",
  "cuillère à café",
] as const;

export type GeneratedRecipeUnit = (typeof GENERATED_RECIPE_UNITS)[number];

/** Fields a model may emit at the recipe root. Anything else is forbidden. */
export const RECIPE_ALLOWED_ROOT_FIELDS = [
  "title",
  "servings",
  "ingredients",
  "steps",
  "prepMinutes",
  "cookMinutes",
  "category",
] as const;

/** Fields a model may emit on an ingredient. */
export const RECIPE_ALLOWED_INGREDIENT_FIELDS = ["name", "quantity", "unit"] as const;

/** Identifier-looking fields that must never appear on an ingredient. */
const FORBIDDEN_ID_FIELDS = [
  "id",
  "product_id",
  "productId",
  "ean",
  "ref",
  "reference",
  "sku",
] as const;

export interface GeneratedRecipeIngredient {
  /** Normalized, non-empty ingredient name. */
  name: string;
  /** Finite number, strictly positive. */
  quantity: number;
  /** Unit from the controlled list. */
  unit: GeneratedRecipeUnit;
}

export interface GeneratedRecipe {
  schemaVersion: typeof GENERATED_RECIPE_SCHEMA_VERSION;
  /** Non-empty title. */
  title: string;
  /** Reference servings the quantities correspond to (integer ≥ 1). */
  servings: number;
  /** Non-empty list of quantified ingredients, without any product identifier. */
  ingredients: GeneratedRecipeIngredient[];
  /** Ordered, non-empty steps. */
  steps: string[];
  /** Optional indicative prep time in minutes — never verified. */
  prepMinutes?: number;
  /** Optional indicative cook time in minutes — never verified. */
  cookMinutes?: number;
  /** Optional dish category, e.g. "plat principal". */
  category?: string;
}

// ---- issue taxonomy ----------------------------------------------------------

export const RECIPE_ISSUE_CODES = [
  "NOT_JSON",
  "NOT_OBJECT",
  "EMPTY_TITLE",
  "INVALID_SERVINGS",
  "EMPTY_INGREDIENTS",
  "INVALID_INGREDIENT",
  "FORBIDDEN_INGREDIENT_FIELD",
  "INGREDIENT_REFERENCE",
  "UNKNOWN_UNIT",
  "INVALID_QUANTITY",
  "EMPTY_STEPS",
  "FORBIDDEN_ROOT_FIELD",
] as const;

export type RecipeIssueCode = (typeof RECIPE_ISSUE_CODES)[number];

export interface RecipeIssue {
  code: RecipeIssueCode;
  /** Human-readable French explanation, usable in a repair prompt. */
  message: string;
  /** Optional pointer into the offending document, e.g. "ingredients[2].unit". */
  path?: string;
}

export interface RecipeParseOk {
  ok: true;
  recipe: GeneratedRecipe;
  /** Number of guided repair rounds consumed before this result (0 when direct). */
  repairs: number;
}

export interface RecipeParseErr {
  ok: false;
  /** Issues found on the last attempt. */
  issues: RecipeIssue[];
  /** Raw output of the last model attempt (already sanitized upstream). */
  raw: string;
  /** Number of guided repair rounds consumed (0 or 1). */
  repairs: number;
}

export type RecipeParseResult = RecipeParseOk | RecipeParseErr;

// ---- strict parse ------------------------------------------------------------

/**
 * Strict parse: the raw string must be a bare JSON object. Markdown fences or
 * surrounding prose are rejected, per the "JSON structuré sans Markdown"
 * decision — the repair prompt then asks for bare JSON.
 */
export function parseRecipeText(raw: string): RecipeParseResult {
  const trimmed = raw.trim();
  let parsed: unknown;
  try {
    parsed = JSON.parse(trimmed);
  } catch {
    return {
      ok: false,
      issues: [
        {
          code: "NOT_JSON",
          message:
            "La sortie n'est pas du JSON pur : aucun Markdown, aucun texte autour de l'objet JSON.",
        },
      ],
      raw: trimmed,
      repairs: 0,
    };
  }
  return validateRecipeObject(parsed, trimmed, 0);
}

// ---- validation ----------------------------------------------------------------

const ALLOWED_ROOT = new Set<string>(RECIPE_ALLOWED_ROOT_FIELDS);
const ALLOWED_INGREDIENT = new Set<string>(RECIPE_ALLOWED_INGREDIENT_FIELDS);
const FORBIDDEN_IDS = new Set<string>(FORBIDDEN_ID_FIELDS);
const UNITS = new Set<string>(GENERATED_RECIPE_UNITS);

function isFiniteNumber(v: unknown): v is number {
  return typeof v === "number" && Number.isFinite(v);
}

function trimmedNonEmpty(v: unknown): string | null {
  return typeof v === "string" && v.trim() !== "" ? v.trim() : null;
}

export function validateRecipeObject(
  parsed: unknown,
  raw: string,
  repairs: number,
): RecipeParseResult {
  const issues: RecipeIssue[] = [];

  if (typeof parsed !== "object" || parsed === null || Array.isArray(parsed)) {
    return {
      ok: false,
      issues: [{ code: "NOT_OBJECT", message: "La recette doit être un objet JSON." }],
      raw,
      repairs,
    };
  }
  const root = parsed as Record<string, unknown>;

  for (const key of Object.keys(root)) {
    if (!ALLOWED_ROOT.has(key)) {
      issues.push({
        code: "FORBIDDEN_ROOT_FIELD",
        message: `Champ '${key}' interdit. Champs autorisés : ${RECIPE_ALLOWED_ROOT_FIELDS.join(", ")}.`,
        path: key,
      });
    }
  }

  if (!trimmedNonEmpty(root.title)) {
    issues.push({ code: "EMPTY_TITLE", message: "Titre requis, chaîne non vide.", path: "title" });
  }

  if (
    !isFiniteNumber(root.servings) ||
    !Number.isInteger(root.servings) ||
    (root.servings as number) < 1
  ) {
    issues.push({
      code: "INVALID_SERVINGS",
      message: "'servings' doit être un entier strictement positif (nombre de convives).",
      path: "servings",
    });
  }

  if (!Array.isArray(root.ingredients) || root.ingredients.length === 0) {
    issues.push({
      code: "EMPTY_INGREDIENTS",
      message: "'ingredients' doit être une liste non vide d'objets {name, quantity, unit}.",
      path: "ingredients",
    });
  } else {
    root.ingredients.forEach((ing, i) => {
      const path = `ingredients[${i}]`;
      if (typeof ing !== "object" || ing === null || Array.isArray(ing)) {
        issues.push({
          code: "INVALID_INGREDIENT",
          message: `${path} doit être un objet {name, quantity, unit}.`,
          path,
        });
        return;
      }
      const ingObj = ing as Record<string, unknown>;
      for (const key of Object.keys(ingObj)) {
        if (FORBIDDEN_IDS.has(key)) {
          issues.push({
            code: "INGREDIENT_REFERENCE",
            message: `${path}.${key} interdit : un ingrédient ne doit jamais contenir d'identifiant produit. Les références viennent uniquement des outils de lecture.`,
            path: `${path}.${key}`,
          });
        } else if (!ALLOWED_INGREDIENT.has(key)) {
          issues.push({
            code: "FORBIDDEN_INGREDIENT_FIELD",
            message: `${path}.${key} interdit. Champs autorisés : name, quantity, unit.`,
            path: `${path}.${key}`,
          });
        }
      }
      if (!trimmedNonEmpty(ingObj.name)) {
        issues.push({ code: "INVALID_INGREDIENT", message: `${path}.name requis, chaîne non vide.`, path: `${path}.name` });
      }
      if (!isFiniteNumber(ingObj.quantity) || (ingObj.quantity as number) <= 0) {
        issues.push({
          code: "INVALID_QUANTITY",
          message: `${path}.quantity doit être un nombre strictement positif.`,
          path: `${path}.quantity`,
        });
      }
      if (typeof ingObj.unit !== "string" || !UNITS.has(ingObj.unit.trim().toLowerCase())) {
        issues.push({
          code: "UNKNOWN_UNIT",
          message: `${path}.unit doit valoir l'une des unités contrôlées : ${GENERATED_RECIPE_UNITS.join(", ")}.`,
          path: `${path}.unit`,
        });
      }
    });
  }

  if (!Array.isArray(root.steps) || root.steps.length === 0) {
    issues.push({
      code: "EMPTY_STEPS",
      message: "'steps' doit être une liste ordonnée non vide de chaînes.",
      path: "steps",
    });
  } else {
    root.steps.forEach((step, i) => {
      if (!trimmedNonEmpty(step)) {
        issues.push({
          code: "EMPTY_STEPS",
          message: `steps[${i}] doit être une chaîne non vide.`,
          path: `steps[${i}]`,
        });
      }
    });
  }

  for (const key of ["prepMinutes", "cookMinutes"] as const) {
    const v = root[key];
    if (v !== undefined && (!isFiniteNumber(v) || (v as number) < 0)) {
      issues.push({
        code: "FORBIDDEN_ROOT_FIELD",
        message: `${key} doit être un nombre de minutes indicatif ≥ 0, ou absent.`,
        path: key,
      });
    }
  }

  if (issues.length > 0) {
    return { ok: false, issues, raw, repairs };
  }

  // All checks passed — build the typed recipe.
  const ingredients: GeneratedRecipeIngredient[] = (
    root.ingredients as Record<string, unknown>[]
  ).map((ing) => ({
    name: trimmedNonEmpty(ing.name) as string,
    quantity: ing.quantity as number,
    unit: (ing.unit as string).trim().toLowerCase() as GeneratedRecipeUnit,
  }));

  const recipe: GeneratedRecipe = {
    schemaVersion: GENERATED_RECIPE_SCHEMA_VERSION,
    title: trimmedNonEmpty(root.title) as string,
    servings: root.servings as number,
    ingredients,
    steps: (root.steps as unknown[]).map((s) => trimmedNonEmpty(s) as string),
    ...(isFiniteNumber(root.prepMinutes) ? { prepMinutes: root.prepMinutes } : {}),
    ...(isFiniteNumber(root.cookMinutes) ? { cookMinutes: root.cookMinutes } : {}),
    ...(trimmedNonEmpty(root.category) ? { category: trimmedNonEmpty(root.category) as string } : {}),
  };
  return { ok: true, recipe, repairs };
}

// ---- single guided repair -------------------------------------------------------

export const MAX_RECIPE_REPAIRS = 1 as const;

/**
 * Build the guided repair prompt for the ONE allowed repair round: the issues
 * found, the rules to satisfy, and the offending raw output (truncated).
 */
export function buildRepairPrompt(raw: string, issues: RecipeIssue[]): string {
  const issueLines = issues.map((i) => `- [${i.code}] ${i.message}${i.path ? ` (à ${i.path})` : ""}`);
  const truncated = raw.length > 2000 ? raw.slice(0, 2000) + "…" : raw;
  return [
    "Ta réponse précédente n'est pas une recette JSON valide. Corrige-la en respectant TOUTES les règles :",
    "sortie = objet JSON unique, sans Markdown ni texte autour ;",
    "champs racine autorisés : " + RECIPE_ALLOWED_ROOT_FIELDS.join(", ") + " ;",
    "chaque ingrédient = exactement {name, quantity, unit} ;",
    "quantity strictement positif ; unit parmi : " + GENERATED_RECIPE_UNITS.join(", ") + " ;",
    "jamais d'identifiant produit (id, product_id, ean…) dans les ingrédients ;",
    "prepMinutes/cookMinutes indicatifs et optionnels.",
    "",
    "Problèmes relevés :",
    ...issueLines,
    "",
    "Ta réponse précédente :",
    truncated,
    "",
    "Renvoie uniquement l'objet JSON corrigé.",
  ].join("\n");
}
